// Simula el mensaje que llega desde WhatsApp.
// Cuando conectes la API real, este nodo se sustituye por el trigger de WhatsApp.

const mensaje = {
  de: 'Marta L.',
  telefono: '+34 6XX XXX XXX',
  hora: '23:41',
  texto: 'Buenas, ¿os queda hueco el jueves?'
};

// Palabras que indican que quiere reservar
const señales = ['cita', 'hueco', 'reservar', 'disponible', 'agendar'];
const texto = mensaje.texto.toLowerCase();

mensaje.quiereCita = señales.some(s => texto.includes(s));

return [{ json: mensaje }];

// Busca los huecos libres del jueves.
// Cuando conectes Google Calendar, este nodo lee la agenda de verdad.

const ocupados = ['09:00', '11:30', '13:00'];
const jornada = ['09:00', '10:00', '11:30', '13:00', '16:00', '17:30'];

const libres = jornada.filter(h => !ocupados.includes(h));

return [{
  json: {
    ...$input.first().json,
    huecos: libres,
    propuesta: libres.slice(0, 2)
  }
}];

// Redacta la respuesta con los huecos encontrados.
// Cuando conectes la API de WhatsApp, este nodo la envía.

const d = $input.first().json;
const [uno, dos] = d.propuesta;

const respuesta = `¡Hola ${d.de.split(' ')[0]}! El jueves me queda a las ${uno} y a las ${dos}. ¿Cuál te viene mejor?`;

return [{
  json: {
    para: d.telefono,
    respuesta,
    respondidoEn: '4 segundos',
    horaMensaje: d.hora
  }
}];

// No pide cita: se avisa a una persona en vez de improvisar una respuesta.

const d = $input.first().json;

return [{
  json: {
    aviso: 'Mensaje que no es una reserva. Lo revisa una persona.',
    de: d.de,
    texto: d.texto
  }
}];
